import type { Question } from '../../lib/types'

export const s3_resilience_questions: Question[] = [
  { id: 'd2-s3r-001', domain: 2, topics: ['S3', 'versioning', 'delete marker'], type: 'single', stem: 'S3 versioning is enabled on a bucket. A user accidentally deletes an object. How can the object be recovered?', options: [{ id: 'A', text: 'The object is permanently deleted and cannot be recovered' }, { id: 'B', text: 'Delete the delete marker — S3 versioning preserves previous versions; deleting the delete marker restores the object' }, { id: 'C', text: 'Restore from S3 Glacier' }, { id: 'D', text: 'Contact AWS Support for object recovery' }], correct: ['B'], explanation: 'When versioning is enabled, deleting an object creates a delete marker (a special version). The previous versions are preserved. Remove the delete marker to restore the object to its previous state.', distractors: { A: 'Versioning prevents permanent deletion of previous versions — the delete marker just hides the object.', C: 'Glacier restore is for archived objects — versioned objects in S3 Standard don\'t go to Glacier automatically.', D: 'No AWS Support needed — delete markers can be removed by bucket owners.' } },
  { id: 'd2-s3r-002', domain: 2, topics: ['S3', 'MFA delete'], type: 'single', stem: 'A company wants to prevent accidental or malicious permanent deletion of S3 objects. Even if access keys are compromised, deletions should require a second factor. What S3 feature provides this?', options: [{ id: 'A', text: 'S3 bucket policy with Deny on DeleteObject' }, { id: 'B', text: 'S3 MFA Delete — requires MFA code in addition to credentials to permanently delete objects or suspend versioning' }, { id: 'C', text: 'S3 Object Lock' }, { id: 'D', text: 'S3 Cross-Region Replication' }], correct: ['B'], explanation: 'S3 MFA Delete requires a valid MFA code for: permanently deleting a versioned object or changing the versioning state of a bucket. Even with full S3 permissions, the operation fails without MFA. Only the root account can enable MFA Delete.', distractors: { A: 'Bucket policies can block some deletions but can be changed by privileged users — MFA Delete can\'t be bypassed even with AWS credentials.', C: 'S3 Object Lock prevents deletion for a specified period — MFA Delete requires real-time MFA verification per action.', D: 'CRR replicates to another region — doesn\'t prevent local deletion.' } },
  { id: 'd2-s3r-003', domain: 2, topics: ['S3', 'replication', 'CRR', 'SRR'], type: 'single', stem: 'A company stores regulatory data in an S3 bucket in us-east-1. Compliance requires a copy of all data to be maintained in another region. What S3 feature provides this?', options: [{ id: 'A', text: 'S3 Same-Region Replication (SRR)' }, { id: 'B', text: 'S3 Cross-Region Replication (CRR) — asynchronously replicates objects to a bucket in a different region' }, { id: 'C', text: 'S3 Transfer Acceleration' }, { id: 'D', text: 'S3 Lifecycle rule to copy to another bucket' }], correct: ['B'], explanation: 'S3 CRR automatically replicates newly uploaded objects to a destination bucket in a different AWS region. Requires versioning enabled on both source and destination. Provides disaster recovery, compliance, and reduced latency for users in another region.', distractors: { A: 'SRR replicates within the same region — not cross-region as required.', C: 'Transfer Acceleration speeds up uploads to a single bucket — not replication.', D: 'Lifecycle rules move/delete objects based on age — not continuous replication to another bucket.' } },
  { id: 'd2-s3r-004', domain: 2, topics: ['S3', 'Object Lock', 'WORM'], type: 'single', stem: 'A financial services firm must store audit logs in S3 such that no one — including administrators — can modify or delete them for 7 years. What S3 feature enforces this?', options: [{ id: 'A', text: 'S3 bucket policy with Deny on DeleteObject' }, { id: 'B', text: 'S3 Object Lock with Compliance mode — prevents deletion/modification by anyone, including root, for the retention period' }, { id: 'C', text: 'S3 MFA Delete' }, { id: 'D', text: 'S3 Object Lock with Governance mode' }], correct: ['B'], explanation: 'S3 Object Lock Compliance mode enforces WORM (Write Once Read Many). No user, including the root account or AWS Support, can delete or modify the object during the retention period. Cannot be unlocked before the retention period expires.', distractors: { A: 'Bucket policies can be removed by privileged users — Object Lock is immutable.', C: 'MFA Delete requires MFA per action but doesn\'t enforce a retention period.', D: 'Governance mode allows users with special permissions to override the lock — not fully immutable.' } },
  { id: 'd2-s3r-005', domain: 2, topics: ['S3', 'lifecycle', 'storage classes'], type: 'single', stem: 'Objects in an S3 bucket are frequently accessed for 30 days after creation, rarely accessed for the next 60 days, and then not needed for daily access but must be retained for 7 years. What lifecycle policy optimizes cost?', options: [{ id: 'A', text: 'Keep all objects in S3 Standard indefinitely' }, { id: 'B', text: 'S3 Standard (0-30 days) → S3 Standard-IA (30-90 days) → S3 Glacier Flexible Retrieval (90 days+)' }, { id: 'C', text: 'Delete after 90 days' }, { id: 'D', text: 'Move to S3 Glacier Instant Retrieval immediately' }], correct: ['B'], explanation: 'Lifecycle policies automate tiering: Standard for hot data (days 0-30), Standard-IA for infrequent access (days 30-90), Glacier for long-term retention (day 90+). This minimizes cost while meeting the 7-year retention requirement.', distractors: { A: 'S3 Standard is expensive for data accessed only occasionally — lifecycle tiering reduces costs significantly.', C: 'Deleting after 90 days violates the 7-year retention requirement.', D: 'Glacier Instant Retrieval charges retrieval fees per GB — immediate archival loses free Standard retrieval benefits for the first 30 days.' } },
  { id: 'd2-s3r-006', domain: 2, topics: ['S3', 'durability', 'availability'], type: 'single', stem: 'What is the durability guarantee of Amazon S3 Standard storage class?', options: [{ id: 'A', text: '99.9% (3 nines)' }, { id: 'B', text: '99.99% (4 nines)' }, { id: 'C', text: '99.999999999% (11 nines)' }, { id: 'D', text: '99.9999999% (9 nines)' }], correct: ['C'], explanation: 'S3 Standard provides 99.999999999% (11 nines) durability by storing data redundantly across a minimum of 3 AZs. This means expected loss of 1 object per 10,000 years per 10 million objects stored.', distractors: { A: '3 nines durability is extremely low — S3\'s durability is far higher.', B: '4 nines is the S3 Standard availability (99.99%) — not the durability.', D: '9 nines is not the correct figure — S3 provides 11 nines of durability.' } },
  { id: 'd2-s3r-007', domain: 2, topics: ['S3', 'replication', 'existing objects', 'batch operations'], type: 'single', stem: 'S3 CRR is configured to replicate new objects to another region. What happens to the 5 TB of existing objects already in the source bucket?', options: [{ id: 'A', text: 'CRR automatically replicates existing objects' }, { id: 'B', text: 'Existing objects are not replicated by CRR — use S3 Batch Operations to replicate them retroactively' }, { id: 'C', text: 'Existing objects are replicated after 24 hours' }, { id: 'D', text: 'Only objects uploaded after CRR is enabled are replicated going forward — no option for existing objects' }], correct: ['B'], explanation: 'CRR only replicates NEW objects (and updates/deletes to existing replicated objects). To replicate existing objects, use S3 Batch Replication (a Batch Operations job) which triggers replication for objects already in the bucket.', distractors: { A: 'CRR does not automatically replicate existing objects at the time of configuration.', C: 'There is no automatic 24-hour backfill for existing objects with CRR.', D: 'S3 Batch Replication does provide the option for existing objects — D is incorrect.' } },
  { id: 'd2-s3r-008', domain: 2, topics: ['S3', 'event notifications', 'Lambda'], type: 'single', stem: 'When an object is uploaded to an S3 bucket (prefix: images/), a Lambda function should automatically create a thumbnail. What triggers the Lambda?', options: [{ id: 'A', text: 'CloudTrail event for PutObject' }, { id: 'B', text: 'S3 Event Notification configured on the bucket for s3:ObjectCreated:* with prefix "images/" targeting Lambda' }, { id: 'C', text: 'EventBridge rule monitoring S3' }, { id: 'D', text: 'Lambda polls the S3 bucket for new objects' }], correct: ['B'], explanation: 'S3 Event Notifications trigger Lambda (or SQS or SNS) when objects are created, deleted, or restored. Configure the event type (ObjectCreated) with optional prefix/suffix filters. This is the simplest and most common S3-to-Lambda trigger.', distractors: { A: 'CloudTrail + EventBridge can trigger Lambda but adds latency and complexity vs. direct S3 event notifications.', C: 'EventBridge S3 events (via CloudTrail) work but require enabling CloudTrail data events — S3 Event Notifications are simpler.', D: 'Lambda cannot poll S3 natively — S3 doesn\'t have a queue-based API like SQS.' } },
  { id: 'd2-s3r-009', domain: 2, topics: ['S3', 'presigned URLs'], type: 'single', stem: 'A web application needs to allow users to download a private S3 file for 15 minutes without making the bucket public. What mechanism provides time-limited access?', options: [{ id: 'A', text: 'Make the S3 object public temporarily' }, { id: 'B', text: 'Generate a pre-signed URL — provides temporary access using the creator\'s credentials for a specified duration' }, { id: 'C', text: 'Create an IAM user for each end user' }, { id: 'D', text: 'Use CloudFront signed URLs' }], correct: ['B'], explanation: 'S3 presigned URLs embed temporary credentials. Generated by IAM users or roles, they grant access to specific S3 operations (GetObject, PutObject) for a defined period. The bucket remains private; the URL becomes invalid after expiration.', distractors: { A: 'Making objects public is permanent until explicitly changed — not time-limited.', C: 'Creating IAM users per end user is not scalable and violates least privilege.', D: 'CloudFront signed URLs require a CloudFront distribution — S3 presigned URLs work directly against the S3 API.' } },
  { id: 'd2-s3r-010', domain: 2, topics: ['S3', 'multipart upload', 'large files'], type: 'single', stem: 'A company uploads very large files (50 GB) to S3. Uploads frequently fail due to network issues, requiring the entire file to be re-uploaded. What should they use?', options: [{ id: 'A', text: 'Increase the S3 request timeout' }, { id: 'B', text: 'S3 Multipart Upload — uploads in parallel parts; failed parts can be retried without restarting the entire upload' }, { id: 'C', text: 'S3 Transfer Acceleration' }, { id: 'D', text: 'Direct Connect' }], correct: ['B'], explanation: 'Multipart Upload splits large files into parts (5 MB to 5 GB each) uploaded in parallel. If a part fails, only that part is retried — not the entire file. AWS recommends multipart upload for files over 100 MB, required for files over 5 GB.', distractors: { A: 'Timeout increases delay when errors occur — doesn\'t prevent network failures.', C: 'Transfer Acceleration uses CloudFront edge locations to speed up uploads — doesn\'t provide resumability.', D: 'Direct Connect provides dedicated bandwidth — doesn\'t provide upload resumability by itself.' } },
  { id: 'd2-s3r-011', domain: 2, topics: ['S3', 'access points', 'VPC'], type: 'single', stem: 'A shared S3 bucket is accessed by multiple teams. Each team should only access their own prefix. Managing bucket policy has become complex. What simplifies access management?', options: [{ id: 'A', text: 'Create separate S3 buckets per team' }, { id: 'B', text: 'S3 Access Points — each team gets a named endpoint with its own access policy scoped to their prefix' }, { id: 'C', text: 'Use S3 ACLs per object' }, { id: 'D', text: 'Create one IAM policy per team' }], correct: ['B'], explanation: 'S3 Access Points simplify access management for shared buckets. Each access point has its own hostname, access policy (scoped to specific prefixes/permissions), and can be restricted to specific VPCs.', distractors: { A: 'Separate buckets work but creates data management overhead — Access Points solve the problem within one bucket.', C: 'ACLs are deprecated and provide object-level control — not prefix-based team access management.', D: 'One IAM policy per team still requires maintaining a complex bucket policy — Access Points delegate this.' } },
  { id: 'd2-s3r-012', domain: 2, topics: ['S3', 'Glacier', 'retrieval tiers'], type: 'single', stem: 'Data archived in S3 Glacier Flexible Retrieval must be restored within 1 hour. Which retrieval option achieves this?', options: [{ id: 'A', text: 'Bulk retrieval (5-12 hours)' }, { id: 'B', text: 'Standard retrieval (3-5 hours)' }, { id: 'C', text: 'Expedited retrieval (1-5 minutes)' }, { id: 'D', text: 'Instant retrieval (immediate)' }], correct: ['C'], explanation: 'Glacier Flexible Retrieval has three tiers: Expedited (1-5 minutes, highest cost), Standard (3-5 hours), and Bulk (5-12 hours, lowest cost). For 1-hour SLA, Expedited retrieval is the only option that guarantees retrieval within minutes.', distractors: { A: 'Bulk retrieval takes 5-12 hours — well over the 1-hour requirement.', B: 'Standard retrieval takes 3-5 hours — exceeds the 1-hour requirement.', D: 'Instant retrieval is a separate storage class (Glacier Instant Retrieval), not a tier of Glacier Flexible Retrieval.' } },
  { id: 'd2-s3r-013', domain: 2, topics: ['S3', 'replication', 'delete marker replication'], type: 'single', stem: 'S3 CRR is configured between two buckets. An object is deleted in the source bucket. Does CRR replicate the delete marker to the destination?', options: [{ id: 'A', text: 'Yes — delete markers are automatically replicated' }, { id: 'B', text: 'No — delete marker replication must be explicitly enabled in the replication configuration' }, { id: 'C', text: 'Deletes are not supported with CRR' }, { id: 'D', text: 'The object is physically deleted from both buckets' }], correct: ['B'], explanation: 'By default, CRR does NOT replicate delete markers. Enable "Delete marker replication" in the replication rule to propagate delete markers. This prevents unintentional deletions in the destination but also means deletion sync is opt-in.', distractors: { A: 'Delete markers must be explicitly enabled for replication — not automatic.', C: 'Deletes (delete markers) can be replicated when configured.', D: 'CRR replicates delete markers (not physical deletion) — objects in the destination have versioning, so physical deletion requires explicit versioned delete.' } },
  { id: 'd2-s3r-014', domain: 2, topics: ['S3', 'CORS'], type: 'single', stem: 'A JavaScript application hosted on domain-a.com needs to make API calls to an S3 bucket on domain-b.s3.amazonaws.com. Requests are being blocked by the browser. What S3 configuration is needed?', options: [{ id: 'A', text: 'Make the S3 bucket public' }, { id: 'B', text: 'Configure S3 CORS policy — allow domain-a.com as an allowed origin for the S3 bucket' }, { id: 'C', text: 'Use CloudFront in front of S3' }, { id: 'D', text: 'Create an IAM user for the JavaScript application' }], correct: ['B'], explanation: 'S3 CORS configuration allows browsers to make cross-origin requests to the bucket. Configure AllowedOrigins, AllowedMethods, and AllowedHeaders. Without CORS, browsers block cross-origin JavaScript requests to S3.', distractors: { A: 'Making the bucket public doesn\'t fix CORS — it\'s a browser security policy, not an access policy issue.', C: 'CloudFront can help but S3 CORS directly solves the issue.', D: 'IAM users are for application credentials — CORS is a browser-side cross-origin policy.' } },
  { id: 'd2-s3r-015', domain: 2, topics: ['S3', 'inventory', 'analytics'], type: 'single', stem: 'A company needs a daily list of all objects in a large S3 bucket (billions of objects) with their metadata (size, last modified, storage class) for compliance reporting. What is the most efficient approach?', options: [{ id: 'A', text: 'Use the AWS CLI to list all objects with --recursive' }, { id: 'B', text: 'S3 Inventory — generates daily or weekly CSV/ORC/Parquet reports of all objects and their metadata' }, { id: 'C', text: 'Query S3 with Athena' }, { id: 'D', text: 'Enable S3 access logging and parse the logs' }], correct: ['B'], explanation: 'S3 Inventory generates scheduled reports (daily or weekly) in CSV, ORC, or Parquet format listing all objects with metadata. For billions of objects, S3 Inventory is far more efficient than listing via API.', distractors: { A: 'AWS CLI list-objects is slow and expensive for billions of objects — API rate limits apply.', C: 'Athena can query S3 but requires data to be queryable — S3 Inventory creates the dataset for Athena to analyze.', D: 'Access logs record individual requests — not a complete object inventory.' } },
  { id: 'd2-s3r-016', domain: 2, topics: ['S3', 'requester pays'], type: 'single', stem: 'A company stores large public datasets in S3 and is paying high data transfer fees for downloads by external users. How can the download costs be shifted to the users downloading the data?', options: [{ id: 'A', text: 'Increase the S3 object pricing' }, { id: 'B', text: 'Enable S3 Requester Pays — the requester (not the bucket owner) pays for requests and data transfer' }, { id: 'C', text: 'Add a usage fee via API Gateway' }, { id: 'D', text: 'Delete files after download' }], correct: ['B'], explanation: 'S3 Requester Pays buckets shift the cost of GET requests and data transfer to the requester. The requester must have an AWS account and include x-amz-request-payer in their requests. Common for public research datasets.', distractors: { A: 'S3 pricing is set by AWS — bucket owners can\'t set per-object pricing.', C: 'API Gateway adds an application layer — Requester Pays is native S3 functionality.', D: 'Deleting files defeats the purpose of storing data for others to download.' } },
  { id: 'd2-s3r-017', domain: 2, topics: ['S3', 'encryption', 'SSE-KMS'], type: 'single', stem: 'A company requires all S3 objects to be encrypted using a customer-managed KMS key. Objects uploaded without encryption should be rejected. How is this enforced?', options: [{ id: 'A', text: 'Enable S3 default encryption with CMK' }, { id: 'B', text: 'Add a bucket policy denying PutObject where the SSE-KMS header specifying the CMK ARN is missing' }, { id: 'C', text: 'Use S3 ACLs to enforce encryption' }, { id: 'D', text: 'Enable S3 server access logging' }], correct: ['B'], explanation: 'A bucket policy with a Deny condition on s3:PutObject where aws:RequestedRegion or the KMS key condition doesn\'t match enforces mandatory CMK encryption. Condition: Null check on x-amz-server-side-encryption-aws-kms-key-id.', distractors: { A: 'Default encryption encrypts objects automatically but doesn\'t reject objects uploaded without the specific CMK.', C: 'S3 ACLs control access to objects — not encryption requirements.', D: 'Access logging records requests — not an enforcement mechanism.' } },
  { id: 'd2-s3r-018', domain: 2, topics: ['S3', 'bucket policy', 'public access'], type: 'single', stem: 'An S3 bucket has a bucket policy allowing public GetObject access. The company also has the S3 Block Public Access setting enabled at the account level. What is the result?', options: [{ id: 'A', text: 'The bucket policy takes precedence — objects are publicly accessible' }, { id: 'B', text: 'Block Public Access overrides the bucket policy — objects are not publicly accessible despite the policy' }, { id: 'C', text: 'Block Public Access and bucket policy conflict — AWS will throw an error' }, { id: 'D', text: 'Only IAM users can access the bucket' }], correct: ['B'], explanation: 'S3 Block Public Access is a guardrail that overrides bucket policies and ACLs. Even if a bucket policy explicitly allows public access, Block Public Access at account or bucket level prevents it. Block Public Access is the final authority.', distractors: { A: 'Block Public Access overrides — the bucket policy is effectively blocked by the guard rail.', C: 'There\'s no conflict error — Block Public Access simply overrides without complaint.', D: 'IAM access is separate from Block Public Access — IAM users with S3 permissions still work.' } },
  { id: 'd2-s3r-019', domain: 2, topics: ['S3', 'Transfer Acceleration'], type: 'single', stem: 'Global users experience slow S3 upload speeds to a bucket in us-east-1 due to long internet paths. What S3 feature improves upload speed for distant users?', options: [{ id: 'A', text: 'S3 Multipart Upload' }, { id: 'B', text: 'S3 Transfer Acceleration — uses CloudFront edge locations to route data over AWS backbone to S3' }, { id: 'C', text: 'S3 Cross-Region Replication' }, { id: 'D', text: 'Direct Connect' }], correct: ['B'], explanation: 'Transfer Acceleration routes data through the nearest CloudFront edge location over the AWS global network to the S3 bucket. This is faster than going over the public internet for long distances. Use a special accelerated endpoint (bucket.s3-accelerate.amazonaws.com).', distractors: { A: 'Multipart Upload improves reliability and parallelism — not geographic routing over the AWS backbone.', C: 'CRR replicates to another region — doesn\'t speed up uploads to the original region.', D: 'Direct Connect is for enterprise on-premises connectivity — not for improving internet-based S3 uploads.' } },
  { id: 'd2-s3r-020', domain: 2, topics: ['S3', 'intelligent tiering'], type: 'single', stem: 'A company stores objects in S3 with unpredictable access patterns — some objects that haven\'t been accessed in months suddenly become hot. What storage class handles this automatically?', options: [{ id: 'A', text: 'S3 Standard-IA — cheaper for infrequently accessed objects' }, { id: 'B', text: 'S3 Intelligent-Tiering — automatically moves objects between frequent and infrequent access tiers based on usage patterns' }, { id: 'C', text: 'S3 Glacier with expedited retrieval' }, { id: 'D', text: 'S3 One Zone-IA' }], correct: ['B'], explanation: 'S3 Intelligent-Tiering monitors access patterns and automatically moves objects to the most cost-effective tier. Objects not accessed for 30 days move to infrequent access; if accessed, they move back to frequent access. No retrieval fees.', distractors: { A: 'Standard-IA charges retrieval fees and requires 30-day minimum storage — re-accessed objects stay expensive.', C: 'Glacier requires explicit lifecycle policies and restore times — not automatic with instant access.', D: 'One Zone-IA has availability risk (single AZ) — not appropriate for objects that might become hot again.' } },
  { id: 'd2-s3r-021', domain: 2, topics: ['S3', 'replication time control', 'RTC'], type: 'single', stem: 'A company has S3 CRR configured and needs a compliance guarantee that 99.99% of objects will be replicated within 15 minutes. What feature provides this SLA?', options: [{ id: 'A', text: 'S3 CRR with versioning' }, { id: 'B', text: 'S3 Replication Time Control (RTC) — provides a 15-minute SLA for 99.99% of object replication' }, { id: 'C', text: 'S3 Batch Replication' }, { id: 'D', text: 'S3 CRR with high-priority rules' }], correct: ['B'], explanation: 'S3 Replication Time Control (RTC) provides an SLA guaranteeing 99.99% of objects are replicated within 15 minutes. It also includes replication metrics (replication latency, bytes pending) via CloudWatch.', distractors: { A: 'Standard CRR replicates typically within minutes but has no formal SLA on timing.', C: 'Batch Replication handles existing objects — not real-time replication SLAs.', D: 'There are no "high-priority" CRR rules in standard configuration — RTC is the feature for guaranteed timing.' } },
  { id: 'd2-s3r-022', domain: 2, topics: ['S3', 'Select', 'cost'], type: 'single', stem: 'A Lambda function reads large CSV files from S3 and processes only specific columns. Downloading entire files wastes bandwidth and Lambda memory. What reduces the data transferred?', options: [{ id: 'A', text: 'Compress the CSV files with gzip' }, { id: 'B', text: 'S3 Select — execute SQL queries on S3 objects directly; only matching data is returned' }, { id: 'C', text: 'Store data in smaller S3 files' }, { id: 'D', text: 'Use DynamoDB instead of S3' }], correct: ['B'], explanation: 'S3 Select allows running simple SQL SELECT queries against CSV, JSON, or Parquet files in S3. Only the matching subset of data is transferred to the client, reducing network transfer by up to 400x and reducing Lambda memory usage.', distractors: { A: 'Compression reduces file size but the entire compressed file still transfers.', C: 'Smaller files would require multiple requests and file management overhead.', D: 'Moving to DynamoDB is a significant architectural change — S3 Select solves it in place.' } },
  { id: 'd2-s3r-023', domain: 2, topics: ['S3', 'Glacier Deep Archive'], type: 'single', stem: 'A media company must retain source video files for 10 years to comply with contractual obligations. Files will never be accessed except in rare legal disputes. What is the most cost-effective storage?', options: [{ id: 'A', text: 'S3 Standard' }, { id: 'B', text: 'S3 Glacier Flexible Retrieval' }, { id: 'C', text: 'S3 Glacier Deep Archive — lowest cost S3 storage, designed for rarely accessed long-term archival' }, { id: 'D', text: 'S3 One Zone-IA' }], correct: ['C'], explanation: 'Glacier Deep Archive is the lowest-cost S3 storage class (~$0.00099/GB/month). Retrieval time is 12-48 hours. Ideal for compliance archives where access is extremely rare. Minimum storage duration is 180 days.', distractors: { A: 'S3 Standard is far more expensive ($0.023/GB vs $0.00099/GB) — costly for 10-year archive.', B: 'Glacier Flexible Retrieval is cheaper than Standard but more expensive than Deep Archive.', D: 'One Zone-IA stores data in only one AZ — risky for 10-year legal compliance data.' } },
  { id: 'd2-s3r-024', domain: 2, topics: ['S3', 'bucket versioning', 'suspend'], type: 'single', stem: 'A company has S3 versioning enabled and now wants to stop creating new versions while keeping existing versions. What is the state after suspending versioning?', options: [{ id: 'A', text: 'Existing versions are deleted' }, { id: 'B', text: 'New uploads overwrite the null version — existing non-null versions are preserved, no new versions created' }, { id: 'C', text: 'All objects revert to a single version' }, { id: 'D', text: 'Versioning cannot be suspended once enabled' }], correct: ['B'], explanation: 'Suspending versioning stops creating new versions. New uploads overwrite the null-versioned object (or create one). All previous non-null versions remain. Once versioning is enabled, it can be suspended but never fully disabled.', distractors: { A: 'Suspending versioning never deletes existing versions.', C: 'Previous versions remain as-is — only new writes are affected by suspension.', D: 'Versioning can be suspended (though not fully disabled after being enabled).' } },
  { id: 'd2-s3r-025', domain: 2, topics: ['S3', 'Object Lock', 'legal hold'], type: 'single', stem: 'An organization is under investigation and must preserve all documents in an S3 bucket indefinitely until the investigation concludes — no specific end date. What S3 Object Lock feature supports this?', options: [{ id: 'A', text: 'Compliance mode with maximum retention period' }, { id: 'B', text: 'S3 Object Lock Legal Hold — indefinite retention without a specific end date, removable by authorized users' }, { id: 'C', text: 'S3 MFA Delete' }, { id: 'D', text: 'Governance mode with long retention period' }], correct: ['B'], explanation: 'Legal Hold puts an Object Lock hold on objects without a retention expiry date. It remains until explicitly removed by an authorized user (s3:PutObjectLegalHold permission). Unlike retention periods, it doesn\'t expire automatically.', distractors: { A: 'Compliance mode with a fixed retention period expires — doesn\'t handle open-ended "until investigation concludes."', C: 'MFA Delete requires MFA per action — doesn\'t enforce indefinite hold.', D: 'Governance mode retention periods have specific end dates and can be overridden by privileged users.' } },
  { id: 'd2-s3r-026', domain: 2, topics: ['S3', 'byte-range fetches'], type: 'single', stem: 'An application needs to download a specific 100 MB segment from the middle of a 10 GB S3 file without downloading the entire file. What S3 capability supports this?', options: [{ id: 'A', text: 'S3 Select for specific byte ranges' }, { id: 'B', text: 'S3 byte-range fetch — download specific byte ranges using the Range HTTP header' }, { id: 'C', text: 'S3 Multipart Download' }, { id: 'D', text: 'S3 Object Tagging to mark segments' }], correct: ['B'], explanation: 'S3 supports the HTTP Range header for partial object retrieval. Specify the byte range in the GET request (Range: bytes=start-end). This downloads only the specified portion, reducing data transfer and costs.', distractors: { A: 'S3 Select queries data content (rows/columns) — not byte-range retrieval of binary data.', C: 'Multipart is for uploads — not selective downloads.', D: 'Object tagging is metadata — not a mechanism for downloading specific byte ranges.' } },
  { id: 'd2-s3r-027', domain: 2, topics: ['S3', 'consistency model'], type: 'single', stem: 'An application writes an object to S3 and immediately reads it back. Is the read guaranteed to return the latest written data?', options: [{ id: 'A', text: 'No — S3 is eventually consistent and may return old data' }, { id: 'B', text: 'Yes — S3 provides strong read-after-write consistency for all operations since December 2020' }, { id: 'C', text: 'Only for new objects — updates are eventually consistent' }, { id: 'D', text: 'Only in us-east-1' }], correct: ['B'], explanation: 'Since December 2020, Amazon S3 provides strong read-after-write consistency for all GET, PUT, LIST operations. A successful write guarantees the next read returns the latest data. This includes overwrites, deletes, and versioned objects.', distractors: { A: 'This was true before December 2020 — S3 now provides strong consistency.', C: 'Strong consistency applies to all objects including updates and deletes — not just new objects.', D: 'S3 strong consistency applies globally across all regions.' } },
  { id: 'd2-s3r-028', domain: 2, topics: ['S3', 'bucket replication', 'bi-directional'], type: 'single', stem: 'A company needs active-active S3 replication between us-east-1 and eu-west-1 — changes in either region should replicate to the other. What configuration enables this?', options: [{ id: 'A', text: 'S3 supports only one-way (unidirectional) replication' }, { id: 'B', text: 'Configure two replication rules — one from us-east-1 to eu-west-1, and one from eu-west-1 to us-east-1' }, { id: 'C', text: 'Use S3 Replication Time Control for bidirectional replication' }, { id: 'D', text: 'Use DynamoDB Global Tables instead' }], correct: ['B'], explanation: 'Bidirectional (two-way) S3 replication is achieved by creating two CRR rules: one in each direction. S3 prevents replication loops for objects that were already replicated. Both buckets must have versioning enabled.', distractors: { A: 'Bidirectional replication is possible with two separate rules.', C: 'Replication Time Control provides SLA guarantees for replication timing — not bidirectional replication. Two rules are still needed.', D: 'DynamoDB Global Tables is unrelated to S3 replication.' } },
  { id: 'd2-s3r-029', domain: 2, topics: ['S3', 'cost', 'storage analysis'], type: 'single', stem: 'A company wants to identify S3 objects that could be moved to cheaper storage classes based on access frequency. What S3 feature provides access pattern analytics?', options: [{ id: 'A', text: 'S3 Inventory' }, { id: 'B', text: 'S3 Storage Class Analysis — analyzes access patterns and provides recommendations for when to transition to Standard-IA' }, { id: 'C', text: 'S3 Select' }, { id: 'D', text: 'AWS Cost Explorer' }], correct: ['B'], explanation: 'S3 Storage Class Analysis monitors access patterns for objects in a bucket/prefix and provides visualization of when objects transition to infrequent access. Use the analysis results to create informed lifecycle policies.', distractors: { A: 'S3 Inventory lists objects and metadata — not access pattern analysis.', C: 'S3 Select queries object contents — not access pattern analytics.', D: 'AWS Cost Explorer shows spending by service — not object-level access patterns for storage optimization.' } },
  { id: 'd2-s3r-030', domain: 2, topics: ['S3', 'website hosting', 'redirect'], type: 'single', stem: 'A company wants to redirect all traffic from an old domain to a new domain using S3 static website hosting. How is this achieved?', options: [{ id: 'A', text: 'Create an S3 bucket with the old domain name configured to redirect all requests to the new domain' }, { id: 'B', text: 'Configure S3 static website hosting redirection rules — redirect all requests to the new domain' }, { id: 'C', text: 'S3 static websites cannot perform redirects' }, { id: 'D', text: 'Use CloudFront function for redirection' }], correct: ['B'], explanation: 'S3 static website hosting supports redirection rules. You can redirect all requests (by setting a redirect-all in the hosting configuration) or use routing rules to redirect specific conditions. The old domain bucket uses S3 website hosting to redirect to the new domain.', distractors: { A: 'The bucket name doesn\'t need to match the domain for this — though for CNAME to work with S3 website endpoints, they must match.', C: 'S3 static websites support both full and conditional redirects.', D: 'CloudFront functions work but S3 website hosting natively supports redirects.' } },
  { id: 'd2-s3r-031', domain: 2, topics: ['S3', 'ACL', 'ownership'], type: 'single', stem: 'An S3 bucket receives objects uploaded by another AWS account. The bucket owner cannot delete these objects because the object owner (the uploader) is different. What setting ensures the bucket owner always owns all objects?', options: [{ id: 'A', text: 'Enable Cross-Region Replication' }, { id: 'B', text: 'Enable S3 Object Ownership (Bucket Owner Enforced) — all objects are owned by the bucket owner regardless of who uploads them' }, { id: 'C', text: 'Add the external account to the bucket policy' }, { id: 'D', text: 'Enable requester pays' }], correct: ['B'], explanation: 'S3 Object Ownership with "Bucket Owner Enforced" setting means the bucket owner owns all objects, even those uploaded by other accounts. ACLs are disabled. This is the recommended setting and eliminates cross-account ownership issues.', distractors: { A: 'CRR replicates objects — doesn\'t change object ownership.', C: 'Bucket policies grant permissions — don\'t change who owns objects.', D: 'Requester pays shifts costs — doesn\'t change object ownership.' } },
  { id: 'd2-s3r-032', domain: 2, topics: ['S3', 'expiration', 'incomplete multipart'], type: 'single', stem: 'An S3 bucket is accumulating storage costs from incomplete multipart uploads (parts uploaded but never completed). How are these cleaned up automatically?', options: [{ id: 'A', text: 'They are cleaned up automatically after 24 hours' }, { id: 'B', text: 'Create an S3 lifecycle rule to expire incomplete multipart uploads after a specified number of days' }, { id: 'C', text: 'Use AWS CLI to manually list and delete incomplete parts' }, { id: 'D', text: 'Enable S3 versioning to prevent incomplete upload accumulation' }], correct: ['B'], explanation: 'S3 lifecycle rules support an "AbortIncompleteMultipartUpload" action that deletes incomplete multipart upload parts after a specified number of days. This prevents storage waste from abandoned uploads.', distractors: { A: 'Incomplete multipart uploads are never automatically cleaned up without a lifecycle rule.', C: 'Manual cleanup with CLI works but is not automated — lifecycle rules are the managed solution.', D: 'Versioning stores multiple versions of complete objects — has no effect on incomplete multipart uploads.' } },
  { id: 'd2-s3r-033', domain: 2, topics: ['S3', 'public access', 'static website'], type: 'single', stem: 'A developer creates an S3 static website but cannot access it publicly. The bucket policy allows public GetObject, but a test URL returns 403 Forbidden. What is likely preventing public access?', options: [{ id: 'A', text: 'The S3 bucket policy has a syntax error' }, { id: 'B', text: 'S3 Block Public Access is enabled — overriding the bucket policy, preventing public access' }, { id: 'C', text: 'Static website hosting is not enabled on the bucket' }, { id: 'D', text: 'The objects must be in a specific prefix for public access' }], correct: ['B'], explanation: 'S3 Block Public Access overrides bucket policies that allow public access. For a static website, Block Public Access must be disabled (or at minimum "Block public access to buckets and objects granted through new bucket policies" must be unchecked).', distractors: { A: 'A policy syntax error would prevent the policy from being saved.', C: 'Static website hosting must be enabled for website features, but object access via bucket policy works without it — ABPA is the more likely culprit here.', D: 'No prefix restriction exists for bucket policies — the policy applies to specified paths.' } },
  { id: 'd2-s3r-034', domain: 2, topics: ['S3', 'Glacier Instant Retrieval'], type: 'single', stem: 'An application accesses archived data approximately once per quarter but requires millisecond retrieval when accessed. Which storage class is most appropriate?', options: [{ id: 'A', text: 'S3 Standard-IA' }, { id: 'B', text: 'S3 Glacier Instant Retrieval — millisecond retrieval for rarely accessed data' }, { id: 'C', text: 'S3 Glacier Flexible Retrieval' }, { id: 'D', text: 'S3 Glacier Deep Archive' }], correct: ['B'], explanation: 'S3 Glacier Instant Retrieval provides millisecond retrieval (like Standard-IA) but at lower storage cost. Designed for data accessed quarterly. 90-day minimum storage duration. Higher retrieval cost than Standard-IA.', distractors: { A: 'Standard-IA is designed for data accessed monthly — more expensive storage than Glacier Instant Retrieval for quarterly access.', C: 'Glacier Flexible Retrieval has 3-5 hour retrieval time — doesn\'t meet millisecond requirement.', D: 'Glacier Deep Archive has 12-48 hour retrieval time — not millisecond.' } },
  { id: 'd2-s3r-035', domain: 2, topics: ['S3', 'server access logging'], type: 'single', stem: 'A security team wants detailed logs of every request made to an S3 bucket for audit purposes. What S3 feature provides request-level logging?', options: [{ id: 'A', text: 'CloudTrail Data Events for S3' }, { id: 'B', text: 'S3 Server Access Logging — delivers logs of all requests to a target S3 bucket' }, { id: 'C', text: 'VPC Flow Logs' }, { id: 'D', text: 'AWS Config for S3' }], correct: ['B'], explanation: 'S3 Server Access Logging records all requests to a bucket (source bucket) and delivers them to a target S3 bucket. Includes request time, IP, action, status, bytes transferred, error code. Note: logs are delivered on a best-effort basis (not guaranteed real-time).', distractors: { A: 'CloudTrail Data Events also logs S3 requests but is more expensive and has strict guarantees — server access logging is lower cost for general audit purposes.', C: 'VPC Flow Logs capture network traffic — not S3 bucket access details.', D: 'AWS Config tracks S3 configuration changes — not individual object request logs.' } },
  { id: 'd2-s3r-036', domain: 2, topics: ['S3', 'replication', 'filtering'], type: 'single', stem: 'An S3 bucket contains objects from multiple departments. Only objects with the tag "department=finance" should be replicated to another region. How is selective replication configured?', options: [{ id: 'A', text: 'Replicate all objects and delete non-finance objects in the destination' }, { id: 'B', text: 'Create a replication rule with an object filter using tag criteria: department=finance' }, { id: 'C', text: 'Create separate S3 buckets per department' }, { id: 'D', text: 'S3 replication can only filter by prefix — not tags' }], correct: ['B'], explanation: 'S3 replication rules support filtering by prefix, tag, or both. Create a rule that replicates only objects with the tag department=finance. Objects without this tag are not replicated.', distractors: { A: 'Replicate-all-and-delete is wasteful — tag-based filtering prevents unnecessary replication.', C: 'Separate buckets per department is a more disruptive change — tag filtering is the targeted solution.', D: 'S3 replication supports tag filtering in addition to prefix filtering.' } },
  { id: 'd2-s3r-037', domain: 2, topics: ['S3', 'bucket policy', 'VPC endpoint'], type: 'single', stem: 'S3 objects should only be accessible from within a specific VPC — all internet access should be blocked. How is this enforced?', options: [{ id: 'A', text: 'S3 Block Public Access' }, { id: 'B', text: 'S3 bucket policy with Condition aws:sourceVpce restricting access to the specific VPC endpoint ID' }, { id: 'C', text: 'S3 VPC Endpoint — automatically restricts access to the VPC' }, { id: 'D', text: 'Network ACL blocking S3' }], correct: ['B'], explanation: 'Use a bucket policy with aws:sourceVpce condition to restrict access to requests from a specific VPC endpoint. Combined with S3 Block Public Access, this ensures only VPC traffic can access the bucket.', distractors: { A: 'Block Public Access prevents public bucket policies/ACLs but doesn\'t limit to a specific VPC.', C: 'A VPC endpoint for S3 provides private connectivity but doesn\'t enforce that only VPC traffic can access — that requires the bucket policy condition.', D: 'Network ACLs control VPC subnet traffic — they can\'t directly control S3 bucket access policies.' } },
  { id: 'd2-s3r-038', domain: 2, topics: ['S3', 'storage lens', 'metrics'], type: 'single', stem: 'A company has hundreds of S3 buckets across multiple accounts. They want visibility into data usage, activity trends, and cost optimization recommendations across all buckets. What AWS service provides this?', options: [{ id: 'A', text: 'S3 Inventory per bucket' }, { id: 'B', text: 'S3 Storage Lens — organization-wide visibility into S3 usage, activity, and recommendations' }, { id: 'C', text: 'AWS Cost Explorer' }, { id: 'D', text: 'CloudWatch S3 metrics' }], correct: ['B'], explanation: 'S3 Storage Lens provides a centralized view of S3 usage and activity metrics across all buckets and accounts in an organization. Includes 85+ metrics, interactive dashboards, and cost optimization recommendations.', distractors: { A: 'S3 Inventory lists objects per bucket — doesn\'t provide cross-account metrics or recommendations.', C: 'Cost Explorer shows billing — not bucket-level S3 usage metrics.', D: 'CloudWatch shows per-bucket metrics — not org-wide aggregated analytics.' } },
  { id: 'd2-s3r-039', domain: 2, topics: ['S3', 'one zone IA', 'use cases'], type: 'single', stem: 'Which workload is APPROPRIATE for S3 One Zone-IA storage?', options: [{ id: 'A', text: 'Primary database backups that must survive AZ failure' }, { id: 'B', text: 'Secondary backup copies that are already replicated elsewhere — S3 One Zone-IA stores data in a single AZ' }, { id: 'C', text: 'Compliance documents with 7-year retention' }, { id: 'D', text: 'Financial transaction logs' }], correct: ['B'], explanation: 'One Zone-IA stores data in a single AZ (20% cheaper than Standard-IA). Appropriate for non-critical, re-creatable data like thumbnail images or secondary backup copies where the primary copy is in Standard/Standard-IA. If the AZ fails, data in One Zone-IA is lost.', distractors: { A: 'Primary backups should be in Standard or Standard-IA for multi-AZ durability — not One Zone-IA.', C: 'Compliance documents need high durability — One Zone-IA\'s single-AZ risk is inappropriate.', D: 'Financial logs are critical records — One Zone-IA provides lower durability.' } },
  { id: 'd2-s3r-040', domain: 2, topics: ['S3', 'versioning', 'cost'], type: 'single', stem: 'S3 versioning is enabled on a bucket and is significantly increasing storage costs. Old versions accumulate indefinitely. How should old versions be managed?', options: [{ id: 'A', text: 'Disable versioning' }, { id: 'B', text: 'Create an S3 lifecycle rule to expire noncurrent versions after a specified number of days or keep only the N most recent versions' }, { id: 'C', text: 'Switch to Glacier for all versions' }, { id: 'D', text: 'Old versions cannot be deleted when versioning is enabled' }], correct: ['B'], explanation: 'Lifecycle rules with NoncurrentVersionExpiration (expire old versions after N days) or NoncurrentVersionTransition (move to cheaper storage) manage version accumulation. Keep the N most recent versions using NoncurrentVersionExpiration with NewerNoncurrentVersions parameter.', distractors: { A: 'Disabling versioning stops new versions — doesn\'t remove existing ones. Also, versioning can only be suspended after being enabled.', C: 'Moving all versions to Glacier may incur minimum storage duration fees for short-lived versions.', D: 'Old versions can and should be deleted via lifecycle rules when no longer needed.' } },
  { id: 'd2-s3r-041', domain: 2, topics: ['S3', 'event notification', 'EventBridge'], type: 'single', stem: 'An application needs to trigger multiple different actions when an object is uploaded to S3 (invoke Lambda, send SNS, and put message in SQS). Using S3 Event Notifications, how can all three targets be notified?', options: [{ id: 'A', text: 'S3 Event Notifications support only one target — use EventBridge for multiple targets' }, { id: 'B', text: 'Configure three separate S3 Event Notification rules — one for each target (Lambda, SNS, SQS)' }, { id: 'C', text: 'S3 supports only Lambda as an event notification target' }, { id: 'D', text: 'Use multiple S3 buckets with separate notifications' }], correct: ['B'], explanation: 'S3 Event Notifications can trigger Lambda functions, SNS topics, and SQS queues. Multiple notification rules can be configured on the same event (with different targets), and EventBridge integration can also be enabled for additional flexibility.', distractors: { A: 'S3 Event Notifications support Lambda, SNS, and SQS as targets, with multiple rules.', C: 'S3 supports Lambda, SNS, and SQS as notification targets.', D: 'Multiple buckets is unnecessarily complex — multiple notification rules on one bucket work fine.' } },
  { id: 'd2-s3r-042', domain: 2, topics: ['S3', 'presigned URL', 'upload'], type: 'single', stem: 'A web app needs to allow users to upload files directly to S3 without routing traffic through the application servers (to reduce bandwidth costs). How can this be implemented securely?', options: [{ id: 'A', text: 'Make the S3 bucket publicly writable' }, { id: 'B', text: 'Generate a presigned PUT URL server-side — users upload directly to S3 using the time-limited URL' }, { id: 'C', text: 'Use S3 Transfer Acceleration for direct uploads' }, { id: 'D', text: 'Provide users with temporary IAM access keys' }], correct: ['B'], explanation: 'Presigned PUT URLs allow direct S3 uploads without going through the application server. The server generates a signed URL with the object key and expiration; the browser uploads directly to S3. Reduces bandwidth costs and server load.', distractors: { A: 'Public write access allows anyone to upload anything — not secure.', C: 'Transfer Acceleration speeds up uploads but doesn\'t enable secure direct upload by end users.', D: 'IAM credentials give broader AWS access — presigned URLs scope access to a specific upload operation.' } },
  { id: 'd2-s3r-043', domain: 2, topics: ['S3', 'metrics', 'request metrics'], type: 'single', stem: 'A team wants CloudWatch metrics for S3 showing request counts, error rates, and latency for a specific prefix within a bucket. What S3 configuration is needed?', options: [{ id: 'A', text: 'S3 request metrics are automatically enabled for all buckets' }, { id: 'B', text: 'Enable S3 request metrics (CloudWatch Request Metrics) for the bucket with a filter — metrics by prefix are supported' }, { id: 'C', text: 'Use VPC Flow Logs to measure S3 traffic' }, { id: 'D', text: 'S3 request metrics are not available at the prefix level' }], correct: ['B'], explanation: 'S3 CloudWatch Request Metrics must be explicitly enabled per bucket with optional filters (prefix, tag, or entire bucket). They provide 1-minute granularity metrics for requests, errors, and latency.', distractors: { A: 'S3 request metrics are NOT automatically enabled — they must be explicitly configured.', C: 'VPC Flow Logs capture network-level traffic — not S3 request metrics.', D: 'Prefix-level filters are supported in S3 request metrics configuration.' } },
  { id: 'd2-s3r-044', domain: 2, topics: ['S3', 'replication', 'ownership override'], type: 'single', stem: 'S3 CRR replicates objects from an account-A bucket to an account-B bucket. The replicated objects are owned by account-A. Account-B users cannot read the replicated objects. What fixes this?', options: [{ id: 'A', text: 'Grant account-B a bucket policy on account-A\'s source bucket' }, { id: 'B', text: 'Enable replication ownership override — replicated objects are automatically owned by the destination bucket owner' }, { id: 'C', text: 'Switch to Same-Region Replication' }, { id: 'D', text: 'Replicated objects always belong to the source account' }], correct: ['B'], explanation: 'Replication ownership override (replica modification sync) changes the ownership of replicated objects to the destination bucket owner. This allows destination account users to access objects without requiring cross-account ACL grants from the source.', distractors: { A: 'A policy on the source bucket doesn\'t change ownership of objects in the destination.', C: 'SRR vs CRR doesn\'t change the ownership issue.', D: 'With ownership override enabled, replicated objects can be owned by the destination account.' } },
  { id: 'd2-s3r-045', domain: 2, topics: ['S3', 'bucket naming', 'exam facts'], type: 'single', stem: 'Which statement about S3 bucket names is CORRECT?', options: [{ id: 'A', text: 'Bucket names are regional — the same name can exist in multiple regions' }, { id: 'B', text: 'Bucket names are globally unique across all AWS accounts and regions' }, { id: 'C', text: 'Bucket names can contain uppercase letters' }, { id: 'D', text: 'Bucket names can be up to 1,024 characters' }], correct: ['B'], explanation: 'S3 bucket names must be globally unique across all AWS accounts and all regions. Names are 3-63 characters, must start with a lowercase letter or number, and can contain only lowercase letters, numbers, and hyphens.', distractors: { A: 'Bucket names are globally unique — not regional. If a name is taken in any region, it\'s taken everywhere.', C: 'Uppercase letters are NOT allowed in S3 bucket names.', D: 'Maximum bucket name length is 63 characters — not 1,024.' } },
]
